const http = this.helpers.httpRequest;

// ⚙️ CONFIG
async function sendMsg(phone, text) {
  return http({
    method: 'POST',
    url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
    body: { number: phone, text: text }
  });
}


// 📱 SUBSCRIBERS
const subscribers = [
  { phone: '573106055920', plan: 'free' },
  // { phone: '573001234567', plan: 'pro' },
];


// 1. Fetch TRM from open.er-api.com (free, no key)
const resp = await http({ method: 'GET', url: 'https://open.er-api.com/v6/latest/USD' });
const cop = resp.rates?.COP || resp.rates?.cop;
if (!cop) throw new Error('TRM API failed');

const date = new Date().toLocaleDateString('es-CO', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'America/Bogota' });

const text = '💵 *TRM Hoy — ' + date + '*\n\n' +
  '🇺🇸 1 USD = 🇨🇴 $' + cop.toLocaleString('es-CO') + ' COP\n\n' +
  '📊 *Conversiones:*\n' +
  '   $10 USD = $' + (10 * cop).toLocaleString('es-CO') + ' COP\n' +
  '   $100 USD = $' + (100 * cop).toLocaleString('es-CO') + ' COP\n' +
  '   $1,000 USD = $' + (1000 * cop).toLocaleString('es-CO') + ' COP\n\n' +
  '⚡ *TRM Alertas*';

// 2. Send
const results = [];
for (const sub of subscribers) {
  try {
    await sendMsg(sub.phone, text);
    results.push({ phone: sub.phone, status: 'sent' });
  } catch (e) {
    results.push({ phone: sub.phone, status: 'error', error: e.message });
  }
}

return { sent: results.filter(r => r.status === 'sent').length, total: subscribers.length, results };
